import{_ as i,l,o as t,c as s,v as e,p as n,x as r,d as p,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"Polymarket / Kalshi 事件合约","description":"","frontmatter":{"title":"Polymarket / Kalshi 事件合约","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/prediction-market-venues.md","filePath":"quant/prediction-market-venues.md","lastUpdated":1789023840000}'),m={name:"quant/prediction-market-venues.md"};function d(c,a,A,B,u,_){const o=l("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="polymarket-kalshi-事件合约" tabindex="-1">Polymarket / Kalshi 事件合约 <a class="header-anchor" href="#polymarket-kalshi-事件合约" aria-label="Permalink to &quot;Polymarket / Kalshi 事件合约&quot;">​</a></h1><div class="epigraph"><p>事件合约把一次可验证的公开结果映射成到期支付 0 或 1 的凭证；场内价格是风险中性概率扣掉费用、抵押与结算基差之后的报价，不是民调的另一个名字。</p><footer>—— 据 Polymarket 与 Kalshi 的公开规则、订单簿与结算说明整理；合约设计对照 Wolfers and Zitzewitz 对预测市场的论述</footer></div><p>预测市场把「某件公开事件会否发生」做成可交易合约。当代两个高可见场所是：Kalshi——美国商品期货交易委员会（CFTC）监管下的指定合约市场，法币清算；Polymarket——以链上抵押与公开订单簿撮合的事件市场，合约用稳定币计价。二者交易的都是<strong>事件合约</strong>（event contract），不是证券现货，也不是本站其他条目里的股票因子。本篇写公开场所的合约结构、抵押、结算与微观结构，为 <a href="/quant/prediction-market-arbitrage">跨市场套利</a> 提供制度前件。只讨论公开规则与公开簿；不讨论如何干扰预言机、绕过地理限制或操纵结算源。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记事件 \\(A\\) 在决议日 \\(T\\) 被裁定为真或假。标准二元合约：</p> \\[\\mathrm{YES}_T=\\mathbf{1}_{\\{A\\text{ 为真}\\}},\\qquad \\mathrm{NO}_T=1-\\mathrm{YES}_T. \\]<p>\\(t\\) 时刻的成交价 \\(p_t^{\\mathrm{YES}}\\in(0,1)\\)（以 1 美元或 1 枚稳定币为单位）在无套利且可完全抵押时，接近风险中性概率 \\(\\mathbb{Q}(A\\mid\\mathcal{F}_t)\\) 减去费用与资金占用。它一般<strong>不等于</strong>真实世界概率 \\(\\mathbb{P}(A)\\)：参与者风险偏好、抵押利率、仓位限制与意见分布都会把 \\(p\\) 推离 \\(\\mathbb{P}\\)。Wolfers 与 Zitzewitz 强调预测市场是信息加总装置；工程上首先要问的是：加总发生在哪一套清算规则上，违约与争议如何结束。</p><p>Kalshi 与 Polymarket 不是同一个加总装置。Kalshi 有中央对手方、会员准入、美元保证金与监管产品清单；事件种类、合约规格与持仓限额写在规则书里。Polymarket 用公开的链上抵押（常见为 USDC 一类稳定币）创建完整集（complete set），订单簿撮合 YES/NO，结算依赖事先写明的决议规则与争议流程。把两个场所的价格画在一张图上当「同一概率」，忽略了货币、准入、费用、决议源与停市条件。</p><h3 id="完整集、抵押与票面-1-元" tabindex="-1">完整集、抵押与票面 1 元 <a class="header-anchor" href="#完整集、抵押与票面-1-元" aria-label="Permalink to &quot;完整集、抵押与票面 1 元&quot;">​</a></h3><p>二元市场的会计单位是完整集：一份 YES 加一份 NO 在决议后合计支付 1。场所通常允许用 1 单位抵押<strong>铸造</strong>完整集，或把完整集<strong>赎回</strong>为 1 单位抵押（扣费前）。因此</p> \\[p^{\\mathrm{YES}}+p^{\\mathrm{NO}}\\approx 1-c, \\]<p>\\(c\\) 为往返费用、点差与铸造赎回摩擦。若两边同时可成交且和显著低于 1，存在买入完整集并持有到结算的锁定（费用后）；显著高于 1 则反向赎回。这是场所内最干净的无风险关系，先于任何跨场所比较。分类市场（多结果互斥且穷尽）把 1 拆到 \\(K\\) 个互斥合约上，和应接近 1。体育与选举的「多候选人」若未穷尽「其他」，和可以合法地不等于 1，那不是套利，是合约没覆盖样本空间。</p><p><span class="marginnote">价格是「每份到期或赔 1 元」的报价。杠杆来自你用更少净值买入 YES，而不是合约本身再乘杠杆倍数。把 0.20 读成「20% 且无资金成本」会漏掉抵押占用、稳定币脱锚与机会成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>读产品说明书，再读簿。</strong> 对每个事件记录：精确的真值定义、决议源（官方统计、认证数据源、场所指定的公开页面）、截止交易时间、争议窗口、是否允许提前决议、持仓与订单限额、费用表。Kalshi 的合约是标准化的监管产品，规格变更走规则；Polymarket 每个市场有自己的决议条款，相近标题的市场不必同分布。回测若用标题字符串匹配事件，会把「候选人 X 当选」与「候选人 X 获得选举人票」当成同一标的。</p><p><strong>订单簿状态。</strong> 两个场所都提供公开的买卖档。可成交概率应用买一/卖一或可执行量加权，而不是最后成交。薄市场里最后成交可以停在过期价上很久。做市与点差随事件临近通常收窄，但在争议期、监管新闻或抵押拥堵时会跳开。容量取可执行深度与持仓限额的最小者。</p><p><strong>时钟与停市。</strong> 选举夜、数据发布、法庭文件都有官方时间戳。场所可能在决议临近暂停匹配，或只允许减仓。用停市后的「概率」去评价预测能力，测的是结算预期，不是实时加总。链上场所还要加上区块确认与抵押到账延迟：你在网页上看到的报价，不等于保证金已经锁定的可执行价。</p><h3 id="决议风险是基差-不是残差噪声" tabindex="-1">决议风险是基差，不是残差噪声 <a class="header-anchor" href="#决议风险是基差-不是残差噪声" aria-label="Permalink to &quot;决议风险是基差，不是残差噪声&quot;">​</a></h3><p>事件合约的独特风险是<strong>决议基差</strong>：链上价格收敛到场所裁定，场所裁定再去贴事先指定的公开源。源延迟、源修订、规则模糊（「以哪家媒体的宣布为准」）会让 \\(p\\to 1\\) 或 \\(0\\) 的最后一跳不等于你对真实世界的判断。Kalshi 作为受监管市场，争议走规则与监管程序；Polymarket 走其公开的决议与争议条款。二者都可以出现「价格早已定价、裁定尚未出」的窗口。把这一窗口里的波动当成 alpha，是在做法律与运营风险，不是在做概率预测。</p>',19)),(t(),n(E,null,{default:r(()=>[h(o,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%85%AC%E5%BC%80%E4%BA%8B%E4%BB%B6%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20MINT%5B%221%20%E5%8D%95%E4%BD%8D%E6%8A%B5%E6%8A%BC%E9%93%B8%E9%80%A0%20YES%2BNO%22%5D%0A%20%20MINT%20--%3E%20BOOK%5B%22%E5%85%AC%E5%BC%80%E8%AE%A2%E5%8D%95%E7%B0%BF%E6%92%AE%E5%90%88%22%5D%0A%20%20BOOK%20--%3E%20PX%5B%22YES%20%2F%20NO%20%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20PX%20--%3E%20RES%5B%22%E6%8C%87%E5%AE%9A%E5%85%AC%E5%BC%80%E6%BA%90%E5%86%B3%E8%AE%AE%22%5D%0A%20%20RES%20--%3E%20PAY%5B%22%E6%94%AF%E4%BB%98%200%20%E6%88%96%201%22%5D%0A%20%20PAY%20--%3E%20REDEEM%5B%22%E5%AE%8C%E6%95%B4%E9%9B%86%E8%B5%8E%E5%9B%9E%E6%8A%B5%E6%8A%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息加总：持不同信念的人把钱放在同一清算所（或同一抵押合约）里，价格成为加权后的风险中性概率。费用与库存使做市商要求价差；极端信念与仓位限额使 \\(p\\) 不必等于 \\(\\mathbb{P}\\)。临近 \\(T\\)，若决议源清晰，时间价值消失，\\(p\\) 被钉向 0/1，点差往往先收后——若出现争议——再张开。这与期权在到期日的钉住类似，但标的是离散事件而不是连续标的价格。</p><p>与民调、博彩公司的差别。民调没有强制的完整集会计，样本权与问题措辞是另一套误差。博彩公司可以调整盘口与限额，不必提供可赎回的 YES+NO=1。预测场所的公开簿让外部观察者能审计深度与费用；这是把它写进量化笔记的理由。与 <a href="/quant/btc-etf-basis">比特币现货 ETF 基差</a> 一类的现金流收敛不同：事件合约没有可交割的「一篮子比特币」，只有裁定文本。收敛质量完全取决于决议条款写得清不清。</p><h3 id="谁能交易、用什么货币" tabindex="-1">谁能交易、用什么货币 <a class="header-anchor" href="#谁能交易、用什么货币" aria-label="Permalink to &quot;谁能交易、用什么货币&quot;">​</a></h3><p>Kalshi：合格参与者、美元、受持仓限额与产品清单约束，适合把事件风险放进传统经纪与清算报告。Polymarket：稳定币抵押、链上结算路径公开，全球可观察的簿更深地暴露在稳定币与链的运营风险上。同一选举事件在两边可以长期存在几分的价差，来源是准入、费用、资本与决议条款，而不自动是「一边更有效」。把链上场所的 24/7 交易当成 Kalshi 的夜盘，会在停市与合规上算错可执行性。</p><p><span class="marginnote">完整集的铸造赎回把预测市场连到固定收益：锁定 YES+NO 等价于把 1 元放到决议日再拿回（扣费）。「无风险」的参照是该抵押品在同期的利率与脱锚风险，不是国债曲线本身。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把网页概率小部件当成可成交价。不要在未读决议源的情况下比较两个标题相似的市场。不要用杠杆账户的收益率去外推场所内 0–1 合约的夏普——那是融资，不是事件溢价。监管状态会变：产品能否对美国零售开放、稳定币是否仍被接受为抵押，都会突然改变深度。这些是制度跳跃，应当成 <a href="/quant/regime-break-risk">体制断裂</a>，而不是抽样噪声。</p><p>本篇不提供如何选择「更容易被裁定争议」的市场，也不讨论攻击结算源。量化用途是：把公开簿、费用、完整集会计和决议条款写成可审计的状态机，然后再谈预测力或套利。预测力检验必须用当时可成交的中间价或买价，并在事件级别做聚类标准误——同一选举的十个相关合约不是十个独立样本。</p><p><span class="marginnote">出处：场所规则以 Kalshi 与 Polymarket 当时有效的公开说明书为准。预测市场作为信息加总见 Wolfers and Zitzewitz。跨场所价差见本站预测市场套利条目。不把民调机构的方法论当成场内结算规则。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件合约是到期支付 0 或 1 的凭证；价格接近风险中性概率，需扣费用、抵押与决议基差。</li><li>Kalshi 是受监管的法币场所，Polymarket 是稳定币抵押的公开簿场所，货币、准入与决议流程不同。</li><li>完整集 YES+NO≈1 是场所内最干净的会计恒等式；分类市场必须检查是否互斥穷尽。</li><li>可执行报价来自订单簿与限额，不来自最后成交或外部概率小部件。</li><li>决议风险是独立的基差来源，应写进条款，而不是残差。</li><li>出处：两场所公开规则；Wolfers and Zitzewitz 对预测市场的论述。</li></ul>',12))])}const b=i(m,[["render",d]]);export{P as __pageData,b as default};
